export const consumerTypes =
    "\nimport { Context } from '@deepseek-ai/cordis';\nimport { apply, type Config, type OfficialSandboxClient } from 'dsh-sandbox-openshell';\ndeclare const client: OfficialSandboxClient;\nconst config: Config = { interactiveClient: client, sandbox: 'typed-consumer', helper: '/opt/dsh-runtime/confine.mjs' };\nasync function contract(ctx: Context) {\n await apply(ctx, config);\n const root: string = ctx.openShellWorkspace.root;\n const target = await ctx.fs.resolve('test', { cwd: root });\n const path: string = ctx.fs.processPath(target);\n const text: string = await ctx.fs.readText(target);\n const stream: AsyncIterable<string> = await ctx.fs.streamText(target);\n return { path, text, stream, mode: ctx.fs.sandboxMode };\n}\nvoid contract;\n";
